'use client';
import {useState} from 'react';import Link from 'next/link';import {useRouter} from 'next/navigation';export default function Register(){const[username,setUsername]=useState('');const[email,setEmail]=useState('');const[password,setPassword]=useState('');const[error,setError]=useState('');const router=useRouter();async function submit(e){e.preventDefault();const r=await fetch('/api/auth/register',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username,email,password})});const d=await r.json();if(r.ok)router.push('/');else setError(d.message||'Registration failed')}return <main className="auth-page"><form className="form-container" onSubmit={submit}><h1>Create Account</h1>{error&&<p className="error-message">{error}</p>}<div className="input-group"><label>Username</label><input required value={username} onChange={e=>setUsername(e.target.value)}/></div><div className="input-group"><label>Email</label><input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></div><div className="input-group"><label>Password</label><input type="password" required minLength={6} value={password} onChange={e=>setPassword(e.target.value)}/><small>Use at least 6 characters</small></div><button className="button primary-button">Register</button><div className="link-container"><Link href="/login">Already have an account?</Link></div></form></main>}
